SELECT lower(actor_login) AS actor, toStartOfMonth(created_at, 'UTC') AS month,
  if(owner IN ('airbytehq', 'hashicorp', 'posthog', 'supabase', 'vercel'), owner, '_ext') AS owner_bucket,
  countIf(event_type = 'PullRequestEvent' AND action = 'opened') AS pr_opened,
  countIf(event_type = 'IssuesEvent' AND action = 'opened') AS issues_opened,
  countIf(event_type = 'PushEvent') AS pushes
FROM (SELECT actor_login, created_at, event_type, action, lower(if(position(repo_name, '/') > 0, substring(repo_name, 1, position(repo_name, '/') - 1), '')) AS owner
      FROM github_events
      WHERE event_type IN ('PushEvent', 'PullRequestEvent', 'IssuesEvent')
        AND lower(actor_login) IN ('tenthirtyam', 'terencecho', 'teresamychu', 'terraformbot', 'terrywilcox', 'tf-sdk-circleci', 'tgallacher', 'tgonzalezc5', 'tgross', 'thaliabarrera', 'thanrahan1', 'tharunk64', 'thebengeu', 'thebigsadowski', 'theccres', 'thehob', 'thejohnny', 'theoskolnik', 'theotherbrian1', 'thetonymaster', 'thewheat', 'thewuster935', 'theyueli', 'thiagosalvatore', 'thisisnotashwin', 'thiskevinwang', 'thmsobrmlr', 'thomashashi', 'thomasrooney', 'thomaszalewski', 'thorfour', 'thorwebdev', 'thoughtpolice', 'thrashr888', 'thyton', 'tiina303', 'tim123abc', 'timarenz', 'timer', 'timeyoutakeit', 'timfallmk', 'timgl', 'timmareddydeekshitha-ship-it', 'timneutkens', 'timolins', 'timothyis', 'timroes', 'tina-wh', 'tism', 'tiwilliam', 'tjcran', 'tjperry07', 'tk1ng', 'tkaemming', 'tkalus', 'tknickman', 'tkorenko', 'tmessi', 'tmunayyer', 'tobias-hashicorp', 'tobiaslins', 'toddgiguere', 'toddmoy', 'tolik0', 'tomasfarias', 'tomashley', 'tomaspozo', 'tombuildsstuff', 'tomcf-hcp', 'tomdale', 'tomh-posthog', 'tomhjp', 'tommyokeefe', 'tonyp-hc', 'tonypan2', 'tootallnate', 'topefolorunso', 'topfunky', 'towe75', 'tpgilmore', 'tr00d', 'tr0njavolta', 'tradel', 'trek', 'trentdibacco', 'trevorleonhc', 'trinhrichard', 'tristanmorgan', 'trodge', 'troyfluegge', 'troyready', 'truenorthcreative', 'trujillo-adam', 'trutled3', 'tryan225', 'tryangul', 'tscolari', 'tstormk', 'tsu019', 'tsuzaki430', 'tuehaulund', 'tuliren', 'tunzor', 'turbocha-supabase', 'turnipdabeets', 'tushar-hashicorp', 'tvo0813', 'tvoran', 'twitnithegirl', 'twixes', 'tybernstein', 'tylerfontaine', 'tylerhillery', 'tylerwolf', 'tymoshokdmytro', 'tyrannosaurus-becks', 'ucheuboh', 'uk1288', 'ungless', 'unstubbable', 'upmitt', 'uruemu', 'usa-reddragon', 'ushakkodali', 'utkarash2991', 'uturunku1', 'v0idpwn', 'vaficionado', 'vaguelyserious', 'vai-airbyte', 'valarissa', 'valerian-roche', 'valeriia-ruban', 'valigula', 'vancluever', 'vanessaxteo', 'vanphan24', 'varunsriramibm', 'vassiedk', 'vbouiller', 'vdekrijger', 'v